import {thermalNoise,thermalMaterials} from './thermal-shaders.js';
import {labMesh,basis} from './lab-geometry.js';
const vs=`attribute vec3 aP;attribute vec3 aN;uniform mat3 uBasis;uniform vec3 uScale;uniform vec3 uCenter;uniform vec2 uSize;uniform vec2 uFit;uniform float uPitch;uniform float uKind;uniform float uTime;varying vec3 vN;varying vec3 vP;varying vec3 vLocal;void main(){vLocal=aP;vec3 local=aP;if(uKind==5.){float tip=(1.-aP.y)*.5;local.x+=sin(aP.y*5.+uTime*12.)*.1*tip;local.z+=cos(aP.y*7.+uTime*10.)*.06*tip;}if(uKind==7.){local.y+=sin(aP.x*17.-uTime*7.)*.055+sin(aP.x*29.-uTime*5.)*.025;}vec3 p=uBasis*(local*uScale)+uCenter;vec3 n=normalize(uBasis*(aN/uScale));float cy=cos(uPitch),sy=sin(uPitch);vP=vec3(p.x,(p.y-uSize.y*.5)*cy+p.z*sy+uSize.y*.5,-(p.y-uSize.y*.5)*sy+p.z*cy);vN=vec3(n.x,n.y*cy+n.z*sy,-n.y*sy+n.z*cy);gl_Position=vec4((vP.x/uSize.x*2.-1.)*uFit.x,(1.-vP.y/uSize.y*2.)*uFit.y,-vP.z/700.,1.);}`;
const fs=`precision highp float;varying vec3 vN;varying vec3 vP;varying vec3 vLocal;uniform vec3 uColor;uniform float uKind;uniform float uAlpha;uniform float uGlow;uniform float uTime;float hash(vec3 p){return fract(sin(dot(p,vec3(12.9898,78.233,32.42)))*43758.5453);}${thermalNoise}void main(){${thermalMaterials}vec3 n=normalize(vN),eye=normalize(vec3(320.,-150.,950.)-vP),light=normalize(vec3(-.45,-.78,1.2));float grain=hash(floor(vLocal*180.)),soft=hash(floor(vLocal*23.));float rough=uKind==0.?.97+.03*sin(vLocal.x*500.+vLocal.z*45.):uKind==3.?.9+.16*grain:.99+.01*grain;float d=max(dot(n,light),0.),fill=max(dot(n,normalize(vec3(.8,-.2,.3))),0.);float spec=pow(max(dot(n,normalize(light+eye)),0.),uKind==0.?65.:uKind==2.?100.:uKind==4.?12.:18.)*(uKind==0.?.65:uKind==2.?.9:uKind==4.?.18:.055);float fres=pow(1.-abs(dot(n,eye)),3.);vec3 color=uColor*rough*(.38+.72*d+.21*fill)+vec3(1.,.97,.87)*spec;float alpha=uAlpha;if(uKind==2.){color=mix(vec3(.47,.57,.55),vec3(.98,.99,.98),min(1.,.35+spec*2.));alpha*=.12+.88*fres;}if(uKind==3.)color*=.88+.16*soft;if(uGlow>0.)color=mix(color,uColor*(1.1+uGlow*.1),min(1.,uGlow));if(uKind==5.){alpha*=smoothstep(.03,.6,abs(dot(n,eye)))*(.9+.1*sin(uTime*16.+vLocal.y*8.));}gl_FragColor=vec4(color,alpha);}`;
const meshCache=new Map();let rendererSequence=0;
export function createLabRenderer(canvas,scene){
 const gl=canvas.getContext('webgl',{alpha:false,antialias:true,preserveDrawingBuffer:true,powerPreference:'low-power'});if(!gl)return null;canvas.dataset.contextId=String(++rendererSequence);
 const resources=[],buffers=new Map();let alive=true,visible=false,frame=0,start=performance.now();
 const shader=(type,source)=>{const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(s));resources.push(()=>gl.deleteShader(s));return s;};let program;
 try{program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vs));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(program));}catch(e){resources.forEach(f=>f());gl.getExtension('WEBGL_lose_context')?.loseContext();return null;}
 resources.push(()=>gl.deleteProgram(program));gl.useProgram(program);gl.enable(gl.DEPTH_TEST);gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);gl.clearColor(.92,.94,.88,1);
 const u=Object.fromEntries(['uBasis','uScale','uCenter','uSize','uFit','uPitch','uColor','uKind','uAlpha','uGlow','uTime'].map(k=>[k,gl.getUniformLocation(program,k)])),ap=gl.getAttribLocation(program,'aP'),an=gl.getAttribLocation(program,'aN');
 function geometry(key){if(buffers.has(key))return buffers.get(key);let mesh=meshCache.get(key);if(!mesh){mesh=labMesh(key);meshCache.set(key,mesh);}const result={count:mesh.positions.length/3};for(const [name,data] of [['p',mesh.positions],['n',mesh.normals]]){const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);result[name]=b;resources.push(()=>gl.deleteBuffer(b));}buffers.set(key,result);return result;}
 function draw(){if(!alive)return;const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const dpr=Math.min(devicePixelRatio||1,1.6),width=Math.round(rect.width*dpr),height=Math.round(rect.height*dpr);if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}gl.viewport(0,0,width,height);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);const state=scene((performance.now()-start)/1000),size=state.size||[640,360];gl.uniform2fv(u.uSize,size);const fit=Math.min(width/size[0],height/size[1]);gl.uniform2f(u.uFit,size[0]*fit/width,size[1]*fit/height);gl.uniform1f(u.uTime,(performance.now()-start)/1000);gl.uniform1f(u.uPitch,state.pitch??.15);const objects=[...state.objects.filter(o=>(o.alpha??1)>=.98),...state.objects.filter(o=>(o.alpha??1)<.98).sort((a,b)=>a.p[2]-b.p[2])];for(const o of objects){const g=geometry(o.shape||'sphere');gl.bindBuffer(gl.ARRAY_BUFFER,g.p);gl.enableVertexAttribArray(ap);gl.vertexAttribPointer(ap,3,gl.FLOAT,false,0,0);gl.bindBuffer(gl.ARRAY_BUFFER,g.n);gl.enableVertexAttribArray(an);gl.vertexAttribPointer(an,3,gl.FLOAT,false,0,0);gl.uniformMatrix3fv(u.uBasis,false,basis(...(o.r||[0,0,0])));gl.uniform3fv(u.uScale,o.s);gl.uniform3fv(u.uCenter,o.p);gl.uniform3fv(u.uColor,o.c);gl.uniform1f(u.uKind,o.kind||0);gl.uniform1f(u.uAlpha,o.alpha??1);gl.uniform1f(u.uGlow,o.glow||0);gl.depthMask((o.alpha??1)>=.98);gl.drawArrays(gl.TRIANGLES,0,g.count);}gl.depthMask(true);canvas.dataset.renderer='webgl';canvas.dataset.objects=String(objects.length);if(visible&&state.animate&&!matchMedia('(prefers-reduced-motion:reduce)').matches)request();}
 function request(){if(frame||!alive)return;frame=requestAnimationFrame(()=>{frame=0;draw();});}
 const resize=new ResizeObserver(request);resize.observe(canvas);const intersection=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)request();},{rootMargin:'80px'});intersection.observe(canvas);request();
 return {render:request,dispose(){alive=false;cancelAnimationFrame(frame);resize.disconnect();intersection.disconnect();resources.reverse().forEach(f=>f());gl.getExtension('WEBGL_lose_context')?.loseContext();}};
}
